CREATE TABLE IF NOT EXISTS `adopt_me`.`v_solicitudes_pendientes` (`id_solicitud` INT, `nombre_solicitante` INT, `nombre_mascota` INT, `nombre_refugio` INT, `fecha_solicitud` INT, `motivo_adopcion` INT);

-- -----------------------------------------------------
-- View `adopt_me`.`v_adopciones`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `adopt_me`.`v_adopciones`;
USE `adopt_me`;
CREATE  OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `adopt_me`.`v_adopciones` AS select `a`.`id_adopcion` AS `id_adopcion`,concat(`u`.`nombres`,' ',`u`.`apellidos`) AS `nombre_adoptante`,`u`.`correo` AS `correo_adoptante`,`m`.`nombre` AS `nombre_mascota`,`m`.`especie` AS `especie`,`r`.`nombre_refugio` AS `nombre_refugio`,`a`.`fecha_adopcion` AS `fecha_adopcion`,`a`.`observaciones` AS `observaciones` from (((`adopt_me`.`adopciones` `a` join `adopt_me`.`usuarios` `u` on(`u`.`id_usuario` = `a`.`id_usuario`)) join `adopt_me`.`mascotas` `m` on(`m`.`id_mascota` = `a`.`id_mascota`)) join `adopt_me`.`refugios` `r` on(`r`.`id_refugio` = `a`.`id_refugio`));

-- -----------------------------------------------------
-- View `adopt_me`.`v_adoptantes_por_refugio`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `adopt_me`.`v_adoptantes_por_refugio`;
USE `adopt_me`;
CREATE  OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `adopt_me`.`v_adoptantes_por_refugio` AS select `a`.`id_refugio` AS `id_refugio`,concat(`u`.`nombres`,' ',`u`.`apellidos`) AS `nombre_adoptante`,`u`.`correo` AS `correo_adoptante`,`m`.`nombre` AS `mascota_adoptada` from ((`adopt_me`.`adopciones` `a` join `adopt_me`.`usuarios` `u` on(`u`.`id_usuario` = `a`.`id_usuario`)) join `adopt_me`.`mascotas` `m` on(`m`.`id_mascota` = `a`.`id_mascota`));

-- -----------------------------------------------------
-- View `adopt_me`.`v_estadisticas_generales`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `adopt_me`.`v_estadisticas_generales`;
USE `adopt_me`;
CREATE  OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `adopt_me`.`v_estadisticas_generales` AS select (select count(0) from `adopt_me`.`mascotas` where `adopt_me`.`mascotas`.`estado_publicacion` = 'publicado') AS `total_mascotas`,(select count(0) from `adopt_me`.`mascotas` where `adopt_me`.`mascotas`.`estado_adopcion` = 'adoptado') AS `total_adoptadas`,(select count(0) from `adopt_me`.`adopciones`) AS `total_adopciones`,(select count(0) from `adopt_me`.`solicitudes_adopcion` where `adopt_me`.`solicitudes_adopcion`.`estado_solicitud` = 'pendiente') AS `total_solicitudes_pendientes`,(select count(0) from `adopt_me`.`usuarios` where `adopt_me`.`usuarios`.`estado_cuenta` = 'activo') AS `total_usuarios_activos`,(select count(0) from `adopt_me`.`refugios` where `adopt_me`.`refugios`.`estado_cuenta` = 'activo') AS `total_refugios_activos`,current_timestamp() AS `fecha_consulta`;

-- -----------------------------------------------------
-- View `adopt_me`.`v_estadisticas_refugio`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `adopt_me`.`v_estadisticas_refugio`;
USE `adopt_me`;
CREATE  OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `adopt_me`.`v_estadisticas_refugio` AS select `r`.`id_refugio` AS `id_refugio`,`r`.`nombre_refugio` AS `nombre_refugio`,count(distinct `m`.`id_mascota`) AS `total_mascotas_publicadas`,count(distinct `s`.`id_solicitud`) AS `total_solicitudes_recibidas`,count(distinct `a`.`id_adopcion`) AS `total_adopciones_concretadas`,current_timestamp() AS `fecha_consulta` from (((`adopt_me`.`refugios` `r` left join `adopt_me`.`mascotas` `m` on(`m`.`id_refugio` = `r`.`id_refugio`)) left join `adopt_me`.`solicitudes_adopcion` `s` on(`s`.`id_refugio` = `r`.`id_refugio`)) left join `adopt_me`.`adopciones` `a` on(`a`.`id_refugio` = `r`.`id_refugio`)) group by `r`.`id_refugio`,`r`.`nombre_refugio`;

-- -----------------------------------------------------
-- View `adopt_me`.`v_mascotas_disponibles`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `adopt_me`.`v_mascotas_disponibles`;
USE `adopt_me`;
CREATE  OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `adopt_me`.`v_mascotas_disponibles` AS select `m`.`id_mascota` AS `id_mascota`,`m`.`nombre` AS `nombre`,`m`.`especie` AS `especie`,`m`.`raza` AS `raza`,`m`.`edad_meses` AS `edad_meses`,`m`.`sexo` AS `sexo`,`m`.`tamanio` AS `tamanio`,`m`.`vacunado` AS `vacunado`,`m`.`esterilizado` AS `esterilizado`,`m`.`descripcion` AS `descripcion`,`r`.`nombre_refugio` AS `nombre_refugio`,`r`.`correo` AS `correo_refugio` from (`adopt_me`.`mascotas` `m` join `adopt_me`.`refugios` `r` on(`r`.`id_refugio` = `m`.`id_refugio`)) where `m`.`estado_adopcion` = 'disponible' and `m`.`estado_publicacion` = 'publicado';

-- -----------------------------------------------------
-- View `adopt_me`.`v_refugios_publicos`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `adopt_me`.`v_refugios_publicos`;
USE `adopt_me`;
CREATE  OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `adopt_me`.`v_refugios_publicos` AS select `r`.`id_refugio` AS `id_refugio`,`r`.`nombre_refugio` AS `nombre_refugio`,`r`.`correo` AS `correo`,`r`.`telefono` AS `telefono`,`r`.`tipo_refugio` AS `tipo_refugio`,`r`.`sitio_web` AS `sitio_web`,count(`m`.`id_mascota`) AS `total_mascotas_publicadas` from (`adopt_me`.`refugios` `r` left join `adopt_me`.`mascotas` `m` on(`m`.`id_refugio` = `r`.`id_refugio` and `m`.`estado_publicacion` = 'publicado' and `m`.`estado_adopcion` = 'disponible')) where `r`.`estado_cuenta` = 'activo' group by `r`.`id_refugio`,`r`.`nombre_refugio`,`r`.`correo`,`r`.`telefono`,`r`.`tipo_refugio`,`r`.`sitio_web`;

-- -----------------------------------------------------
-- View `adopt_me`.`v_solicitudes_pendientes`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `adopt_me`.`v_solicitudes_pendientes`;
USE `adopt_me`;
CREATE  OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `adopt_me`.`v_solicitudes_pendientes` AS select `s`.`id_solicitud` AS `id_solicitud`,concat(`u`.`nombres`,' ',`u`.`apellidos`) AS `nombre_solicitante`,`m`.`nombre` AS `nombre_mascota`,`r`.`nombre_refugio` AS `nombre_refugio`,`s`.`fecha_solicitud` AS `fecha_solicitud`,`s`.`motivo_adopcion` AS `motivo_adopcion` from (((`adopt_me`.`solicitudes_adopcion` `s` join `adopt_me`.`usuarios` `u` on(`u`.`id_usuario` = `s`.`id_usuario`)) join `adopt_me`.`mascotas` `m` on(`m`.`id_mascota` = `s`.`id_mascota`)) join `adopt_me`.`refugios` `r` on(`r`.`id_refugio` = `s`.`id_refugio`)) where `s`.`estado_solicitud` = 'pendiente';
USE `adopt_me`;

DELIMITER $$
USE `adopt_me`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `adopt_me`.`trg_aprobar_adopcion`
AFTER UPDATE ON `adopt_me`.`solicitudes_adopcion`
FOR EACH ROW
BEGIN

    IF OLD.estado_solicitud = 'pendiente'
       AND NEW.estado_solicitud = 'aprobada' THEN

        UPDATE mascotas
        SET estado_adopcion = 'adoptado'
        WHERE id_mascota = NEW.id_mascota;

    END IF;

END$$

USE `adopt_me`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `adopt_me`.`trg_historial_estado_solicitud`
AFTER UPDATE ON `adopt_me`.`solicitudes_adopcion`
FOR EACH ROW
BEGIN

    IF OLD.estado_solicitud <> NEW.estado_solicitud THEN

        INSERT INTO historial_solicitudes (
            id_solicitud,
            estado_anterior,
            estado_nuevo
        )
        VALUES (
            NEW.id_solicitud,
            OLD.estado_solicitud,
            NEW.estado_solicitud
        );

    END IF;

END$$


